/* tooltip */
.tp-zone{position:relative;display:flex;flex-direction:column;align-items:center;gap:30px;padding:30px 0}
.tp-bar{display:flex;align-items:center;gap:2px;padding:4px;background:var(--panel);border:1px solid var(--line)}
.tp-btn{width:36px;height:36px;display:grid;place-items:center;color:var(--text-dim);transition:color .2s,background-color .2s}
.tp-btn:hover,.tp-btn:focus-visible{color:var(--text);background:var(--chip);outline:none}
.tp-sep{width:1px;height:20px;background:var(--line);margin:0 4px}
.tp-info{display:inline-flex;align-items:center;gap:6px;font-size:13px;color:var(--text-dim);border-bottom:1px dashed var(--icon-line);padding-bottom:1px}
.tp-info:hover,.tp-info:focus-visible{color:var(--text);outline:none}
.tp{position:absolute;left:0;top:0;z-index:5;display:flex;align-items:center;gap:8px;padding:6px 9px;background:var(--text);color:var(--panel);font-size:12px;font-weight:500;white-space:nowrap;pointer-events:none;opacity:0;transform:translate(-50%,calc(-100% - 6px)) translateY(4px);transition:opacity .16s ease,transform .25s var(--ease)}
.tp.show{opacity:1;transform:translate(-50%,calc(-100% - 6px))}
.tp.below{transform:translate(-50%,6px) translateY(-4px)}
.tp.below.show{transform:translate(-50%,6px)}
.tp-k{font-family:var(--mono);font-size:10.5px;opacity:.65}
.tp-k:empty{display:none}
.tp-d{display:none}
.tp.rich{flex-direction:column;align-items:flex-start;gap:3px;white-space:normal;width:230px;padding:10px 12px;background:var(--panel);color:var(--text);border:1px solid var(--icon-line);box-shadow:0 12px 30px -14px rgba(0,0,0,.35)}
.tp.rich .tp-t{font-weight:600;font-size:13px}
.tp.rich .tp-d{display:block;font-size:12.5px;line-height:1.5;color:var(--text-dim);font-weight:400}

/* ---------- tooltip ---------- */
{
  const zone = $('#tp-zone'), tip = $('#tp'), tt = $('.tp-t', tip), tk = $('.tp-k', tip), td = $('.tp-d', tip);
  let place = 'top', timer = null, cur = null;
  function show(el){
    cur = el; const rich = !!el.dataset.rich;
    tip.classList.toggle('rich', rich);
    tt.textContent = rich ? 'Who can see this' : el.dataset.tip;
    tk.textContent = rich ? '' : (el.dataset.key || '');
    td.textContent = rich ? 'Anyone at DesignMe with the link can view this page, and only editors can change it.' : '';
    const z = zone.getBoundingClientRect(), r = el.getBoundingClientRect();
    tip.style.left = (r.left - z.left + r.width / 2) + 'px';
    tip.style.top = ((place === 'top' ? r.top : r.bottom) - z.top) + 'px';
    tip.classList.toggle('below', place === 'bottom');
    requestAnimationFrame(() => tip.classList.add('show'));
  }
  function hide(){ clearTimeout(timer); cur = null; tip.classList.remove('show'); }
  $$('[data-tip],[data-rich]', zone).forEach(el => {
    el.addEventListener('mouseenter', () => { clearTimeout(timer); timer = setTimeout(() => { show(el); Sound.play('stream'); }, tip.classList.contains('show') ? 0 : 140); });
    el.addEventListener('mouseleave', hide);
    el.addEventListener('focus', () => show(el));
    el.addEventListener('blur', hide);
    el.addEventListener('click', () => Sound.play('tick'));
  });
  tabHandlers.tip = v => { place = v; if (cur) show(cur); };
}
